package main

import "fmt"

// Node represents a node in the binary tree.
// It can function as a branch (with children) or a leaf (without children).
type Node struct {
	Value int
	Left  *Node
	Right *Node
}

// treeSum recursively calculates the sum of all values in the tree.
func treeSum(n *Node) int {
	if n == nil {
		return 0
	}
	return n.Value + treeSum(n.Left) + treeSum(n.Right)
}

func main() {
	// Create the tree:
	//         5
	//        / \
	//       3   8
	//      / \   \
	//     1   4   10
	root := &Node{
		Value: 5,
		Left: &Node{
			Value: 3,
			Left:  &Node{Value: 1}, // Leaf
			Right: &Node{Value: 4}, // Leaf
		},
		Right: &Node{
			Value: 8,
			Right: &Node{Value: 10}, // Leaf
		},
	}

	// Calculate and print the sum
	fmt.Println(treeSum(root))
}

