class Leaf:
    def __init__(self, value):
        self.value = value

class Branch:
    def __init__(self, left, value, right):
        self.left = left
        self.value = value
        self.right = right

def treeSum(node):
    if isinstance(node, Leaf):
        return node.value
    return treeSum(node.left) + node.value + treeSum(node.right)

