    Branch(Leaf(1), 3, Leaf(4)),
    5,
    Branch(None, 8, Leaf(10))
)

# Adjust for Branch with None left
def treeSumSafe(node):
    if node is None:
        return 0
    if isinstance(node, Leaf):
        return node.value
    return treeSumSafe(node.left) + node.value + treeSumSafe(node.right)

