module benchmark/solution

import std/io (println)

export type SortedSet = SNil | SCons(int, SortedSet)

-- Get the length of a sorted set
export func sLength(s: SortedSet) -> int ! {} =
  match s {
    SNil => 0,
    SCons(_, rest) => 1 + sLength(rest)
  }

-- Check if a sorted set is properly sorted (and has no duplicates)
export func isSorted(s: SortedSet) -> bool ! {} =
  match s {
    SNil => true,
    SCons(x, SNil) => true,
    SCons(x, SCons(y, rest)) => x < y && isSorted(SCons(y, rest))
  }

-- Merge two sorted sets (union operation)
export func sMerge(a: SortedSet, b: SortedSet) -> SortedSet ! {}
ensures { isSorted(result) } {
  match a {
    SNil => b,
    SCons(x, aRest) =>
      match b {
        SNil => a,
        SCons(y, bRest) =>
          if x < y then SCons(x, sMerge(aRest, b))
          else if x > y then SCons(y, sMerge(a, bRest))
          else SCons(x, sMerge(aRest, bRest))
      }
  }
}

-- Intersect two sorted sets
export func sIntersect(a: SortedSet, b: SortedSet) -> SortedSet ! {}
ensures { isSorted(result) } {
  match a {
    SNil => SNil,
    SCons(x, aRest) =>
      match b {
        SNil => SNil,
        SCons(y, bRest) =>
          if x < y then sIntersect(aRest, b)
          else if x > y then sIntersect(a, bRest)
          else SCons(x, sIntersect(aRest, bRest))
      }
  }
}

-- Convert a sorted set to string representation
export func toStr(s: SortedSet) -> string ! {} =
  match s {
    SNil => "{}",
    SCons(x, rest) => "{" ++ elementsToStr(s) ++ "}"
  }

pure func elementsToStr(s: SortedSet) -> string ! {} =
  match s {
    SNil => "",
    SCons(x, SNil) => show(x),
    SCons(x, rest) => show(x) ++ "," ++ elementsToStr(rest)
  }

-- Proof that merge preserves sortedness
export func mergePreservesSorted(a: SortedSet, b: SortedSet) -> bool ! {}
ensures { result == true } {
  isSorted(sMerge(a, b))
}

-- Proof of inclusion-exclusion principle: |A∪B| + |A∩B| == |A| + |B|
export func inclusionExclusion(a: SortedSet, b: SortedSet) -> bool ! {}
ensures { result == true } {
  let unionSet = sMerge(a, b);
  let intersectSet = sIntersect(a, b);
  let lhs = sLength(unionSet) + sLength(intersectSet);
  let rhs = sLength(a) + sLength(b);
  lhs == rhs
}

export func main() -> () ! {IO} {
  let setA = SCons(1, SCons(3, SCons(5, SNil)));
  let setB = SCons(2, SCons(3, SCons(4, SNil)));
  let merged = sMerge(setA, setB);
  let intersected = sIntersect(setA, setB);

  println(toStr(merged));
  println(toStr(intersected));
  println(show(sLength(merged)));
  println(show(isSorted(merged)));
  println(show(mergePreservesSorted(setA, setB)));
  println(show(inclusionExclusion(setA, setB)))
}

