pure func parseOrder(j: Json) -> Option[{id: int, item: string, qty: int, price: float}] =
  match getInt(j, "id") {
    Some(id) => match getString(j, "item") {
      Some(item) => match getInt(j, "qty") {
        Some(qty) => match getNumber(j, "price") {
          Some(price) => Some({id: id, item: item, qty: qty, price: price}),
          None => None
        },
        None => None
      },
      None => None
    },
    None => None
  }

pure func parseOrders(js: [Json]) -> [{id: int, item: string, qty: int, price: float}] =
  match js {
    [] => [],
    j :: rest =>
      match parseOrder(j) {
        Some(o) => o :: parseOrders(rest),
        None => parseOrders(rest)
      }
  }

pure func total(order: {id: int, item: string, qty: int, price: float}) -> float =
  intToFloat(order.qty) * order.price

pure func filterHigh(orders: [{id: int, item: string, qty: int, price: float}], limit: float) -> [{id: int, item: string, qty: int, price: float}] =
  match orders {
    [] => [],
    o :: rest =>
      if total(o) > limit then
        o :: filterHigh(rest, limit)
      else
        filterHigh(rest, limit)
  }

func printOrders(orders: [{id: int, item: string, qty: int, price: float}]) -> () ! {IO} =
  match orders {
    [] => (),
    o :: rest => {
      println(o.item ++ ": " ++ show(total(o)));
      printOrders(rest)
    }
  }

