  match decode(jsonStr) {
    Ok(j) => {
      match asArray(j) {
        Some(arr) => {
          let orders = parseOrders(arr);
          let filtered = filterHigh(orders, 5.0);
          printOrders(filtered)
        },
        None => println("Not an array")
      }
    },
    Err(msg) => println("Parse error: " ++ msg)
  }
}

