type Term =
  | TVar(string)
  | TLam(string, Term)
  | TApp(Term, Term)

export func subst(t: Term, v: string, r: Term) -> Term {
  match t {
    TVar(x) =>
      if x == v
      then r
      else TVar(x),
    TLam(x, body) =>
      if x == v
      then TLam(x, body)
      else TLam(x, subst(body, v, r)),
    TApp(f, a) =>
      TApp(subst(f, v, r), subst(a, v, r))
  }
}

export func isValue(t: Term) -> bool {
  match t {
    TLam(_, _) => true,
    TVar(_) => true,
    TApp(_, _) => false
  }
}

export func eval(t: Term) -> Term {
  match t {
    TVar(x) => TVar(x),
    TLam(x, body) => TLam(x, body),
    TApp(f, a) => {
      let fv = eval(f);
      let av = eval(a);
      match fv {
        TLam(x, body) =>
          eval(subst(body, x, av)),
        _ =>
          TApp(fv, av)
      }
    }
  }
}

