from typing import List, Tuple, Any

@dataclass
class Expr:
    pass

@dataclass
class Num(Expr):
    value: int

@dataclass
class Var(Expr):
    name: str

@dataclass
class Add(Expr):
    left: Expr
    right: Expr

@dataclass
class Mul(Expr):
    left: Expr
    right: Expr

@dataclass
class Let(Expr):
    name: str
    value: Expr
    body: Expr

Env = List[Tuple[str, Any]]

def lookup(name: str, env: Env) -> Any:
    for var_name, value in env:
        if var_name == name:
            return value
    raise NameError(f"Variable {name} not found")

def eval(expr: Expr, env: Env) -> Any:
    match expr:
        case Num(value):
            return value
        case Var(name):
            return lookup(name, env)
        case Add(left, right):
            return eval(left, env) + eval(right, env)
        case Mul(left, right):
            return eval(left, env) * eval(right, env)
        case Let(name, value, body):
            new_env = [(name, eval(value, env))] + env
            return eval(body, new_env)

