package main

import "fmt"

type TreeKind int

const (
	KindLeaf TreeKind = iota
	KindNode
)

type Tree struct {
	kind  TreeKind
	value int
	left  *Tree
	right *Tree
}

func Leaf(value int) *Tree {
	return &Tree{kind: KindLeaf, value: value}
}

func Node(left *Tree, value int, right *Tree) *Tree {
	return &Tree{kind: KindNode, value: value, left: left, right: right}
}

func treeSum(t *Tree) int {
	switch t.kind {
	case KindLeaf:
		return t.value
	case KindNode:
		return treeSum(t.left) + t.value + treeSum(t.right)
	default:
		panic("unknown tree kind")
	}
}

func findMax(t *Tree) int {
	switch t.kind {
	case KindLeaf:
		return t.value
	case KindNode:
		leftMax := findMax(t.left)
		rightMax := findMax(t.right)
		max := t.value
		if leftMax > max {
			max = leftMax
		}
		if rightMax > max {
			max = rightMax
		}
		return max
	default:
		panic("unknown tree kind")
	}
}

func main() {
	tree := Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)))
	sum := treeSum(tree)
	max := findMax(tree)
	fmt.Printf("Sum: %d\n", sum)
	fmt.Printf("Max: %d\n", max)
}

