type Color = Red | Black

type RBTree = Empty | Node(Color, RBTree, int, RBTree)

export func balance(color: Color, left: RBTree, value: int, right: RBTree) -> RBTree {
  match (color, left, value, right) {
    -- Left-Left
    (Black,
      Node(Red, Node(Red, a, x, b), y, c),
      z,
      d
    ) =>
      Node(Red,
        Node(Black, a, x, b),
        y,
        Node(Black, c, z, d)
     ),

    -- Left-Right
    (Black,
      Node(Red, a, x, Node(Red, b, y, c)),
      z,
      d
    ) =>
      Node(Red,
        Node(Black, a, x, b),
        y,
        Node(Black, c, z, d)
     ),

    -- Right-Left
    (Black,
      a,
      x,
      Node(Red, Node(Red, b, y, c), z, d)
    ) =>
      Node(Red,
        Node(Black, a, x, b),
        y,
        Node(Black, c, z, d)
     ),

    -- Right-Right
    (Black,
      a,
      x,
      Node(Red, b, y, Node(Red, c, z, d))
    ) =>
      Node(Red,
        Node(Black, a, x, b),
        y,
        Node(Black, c, z, d)
     ),

    -- Default: no balancing needed
    _ => Node(color, left, value, right)
  }
}

export func insertHelper(x: int, tree: RBTree) -> RBTree {
  match tree {
    Empty => Node(Red, Empty, x, Empty),
    Node(color, left, v, right) =>
      if x < v
      then balance(color, insertHelper(x, left), v, right)
      else if x > v
      then balance(color, left, v, insertHelper(x, right))
      else tree
  }
}

export func makeBlack(tree: RBTree) -> RBTree {
  match tree {
    Empty => Empty,
    Node(_, left, v, right) => Node(Black, left, v, right)
  }
}

export func insert(x: int, tree: RBTree) -> RBTree =
  makeBlack(insertHelper(x, tree))

export func inorder(tree: RBTree) -> [int] {
  match tree {
    Empty => [],
    Node(_, left, v, right) =>
      let l = inorder(left) in
      let r = inorder(right) in
      concatLists(l, v :: r)
  }
}

export func concatLists[a](xs: [a], ys: [a]) -> [a] {
  match xs {
    [] => ys,
    h :: t => h :: concatLists(t, ys)
  }
}

export func insertList(xs: [int], tree: RBTree) -> RBTree {
  match xs {
    [] => tree,
    h :: t => insertList(t, insert(h, tree))
  }
}

export func inorderToString(xs: [int]) -> string {
  match xs {
    [] => "",
    [x] => show(x),
    x :: rest => show(x) ++ " " ++ inorderToString(rest)
  }
}

