from dataclasses import dataclass
from typing import Optional

Red = 'Red'
Black = 'Black'

@dataclass
class Node:
    color: str
    left: Optional['Node']
    value: int
    right: Optional['Node']

def balance(color, left, value, right):
    match (color, left, value, right):
        case ('Black', Node('Red', Node('Red', a, x, b), y, c), z, d):
            return Node('Red', Node('Black', a, x, b), y, Node('Black', c, z, d))
        case ('Black', Node('Red', a, x, Node('Red', b, y, c)), z, d):
            return Node('Red', Node('Black', a, x, b), y, Node('Black', c, z, d))
        case ('Black', a, x, Node('Red', Node('Red', b, y, c), z, d)):
            return Node('Red', Node('Black', a, x, b), y, Node('Black', c, z, d))
        case ('Black', a, x, Node('Red', b, y, Node('Red', c, z, d))):
            return Node('Red', Node('Black', a, x, b), y, Node('Black', c, z, d))
        case _:
            return Node(color, left, value, right)

def insert(x, tree):
    def ins(node):
        if node is None:
            return Node(Red, None, x, None)
        if x < node.value:
            return balance(node.color, ins(node.left), node.value, node.right)
        elif x > node.value:
            return balance(node.color, node.left, node.value, ins(node.right))
        else:
            return node

    res = ins(tree)
    return Node(Black, res.left, res.value, res.right)

def inorder(tree):
    if tree is None:
        return []
    return inorder(tree.left) + [tree.value] + inorder(tree.right)

def main():
    values = [7, 3, 18, 10, 22, 8, 11, 26]
    tree = None
    for v in values:
        tree = insert(v, tree)
    print(inorder(tree))

if __name__ == '__main__':
    main()

