package main

import "fmt"

type StateKind int

const (
	StateIdle StateKind = iota
	StateMoving
	StateDoorOpen
)

type State struct {
	kind    StateKind
	floor   int
	target  int
	timer   int
}

type EventKind int

const (
	EventCall EventKind = iota
	EventTick
	EventArrive
)

type Event struct {
	kind  EventKind
	floor int
}

func transition(s State, e Event) State {
	switch s.kind {
	case StateIdle:
		switch e.kind {
		case EventCall:
			if e.floor == s.floor {
				return State{kind: StateDoorOpen, floor: s.floor, timer: 3}
			}
			return State{kind: StateMoving, floor: s.floor, target: e.floor}
		default:
			return s
		}
	case StateMoving:
		switch e.kind {
		case EventTick:
			return s
		case EventArrive:
			return State{kind: StateDoorOpen, floor: s.target, timer: 3}
		default:
			return s
		}
	case StateDoorOpen:
		switch e.kind {
		case EventTick:
			if s.timer > 1 {
				return State{kind: StateDoorOpen, floor: s.floor, timer: s.timer - 1}
			}
			return State{kind: StateIdle, floor: s.floor}
		default:
			return s
		}
	default:
		return s
	}
}

func display(s State) string {
	switch s.kind {
	case StateIdle:
		return fmt.Sprintf("IDLE @ floor %d", s.floor)
	case StateMoving:
		return fmt.Sprintf("MOVING %d -> %d", s.floor, s.target)
	case StateDoorOpen:
		return fmt.Sprintf("DOOR_OPEN @ floor %d (%dsec)", s.floor, s.timer)
	default:
		return "UNKNOWN"
	}
}

