// Algebraic Data Types for State
const State = {
  Idle: (floor) => ({ type: 'Idle', floor }),
  Moving: (current, target) => ({ type: 'Moving', current, target }),
  DoorOpen: (floor, timer) => ({ type: 'DoorOpen', floor, timer }),
};

// Algebraic Data Types for Event
const Event = {
  Call: (floor) => ({ type: 'Call', floor }),
  Tick: () => ({ type: 'Tick' }),
  Arrive: () => ({ type: 'Arrive' }),
};

// Transition function with exhaustive pattern matching
function transition(state, event) {
  switch (state.type) {
    case 'Idle':
      switch (event.type) {
        case 'Call':
          return event.floor === state.floor
            ? State.DoorOpen(state.floor, 3)
            : State.Moving(state.floor, event.floor);
        case 'Tick':
        case 'Arrive':
          return state;
      }
      break;
    case 'Moving':
      switch (event.type) {
        case 'Tick':
          return state;
        case 'Arrive':
          return State.DoorOpen(state.target, 3);
        case 'Call':
          return state;
      }
      break;
    case 'DoorOpen':
      switch (event.type) {
        case 'Tick':
          return state.timer > 1
            ? State.DoorOpen(state.floor, state.timer - 1)
            : State.Idle(state.floor);
        case 'Call':
        case 'Arrive':
          return state;
      }
      break;
  }
  return state;
}

// Display function
function display(state) {
  switch (state.type) {
    case 'Idle':
      return `IDLE @ floor ${state.floor}`;
    case 'Moving':
      return `MOVING ${state.current} -> ${state.target}`;
    case 'DoorOpen':
      return `DOOR_OPEN @ floor ${state.floor} (${state.timer}sec)`;
  }
}

