type Event = Tick | Reset

func transition(state: State, event: Event) -> State {
  match (state, event) {
    (Green(t), Tick) => if t > 1 then Green(t - 1) else Yellow(3),
    (Yellow(t), Tick) => if t > 1 then Yellow(t - 1) else Red(10),
