    Yellow(n) => "YELLOW (" ++ show(n) ++ "sec)",
    Red(n) => "RED (" ++ show(n) ++ "sec)"
  }
}

func stepTicks(n: int, s: State) -> State ! {IO} {
  if n <= 0 then s else {
    let next = transition(s, Tick);
    print(display(next));
    stepTicks(n - 1, next)
  }
}

export func main() -> () ! {IO} {
  let s0 = Green(20);
  let s1 = stepTicks(25, s0);
  let s2 = transition(s1, Reset);
  print(display(s2));
  let _ = stepTicks(5, s2);
  ()
}

