from dataclasses import dataclass

@dataclass
class Const:
    value: int

@dataclass
class Var:
    name: str

@dataclass
class Add:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Mul:
    left: 'Expr'
    right: 'Expr'

Expr = Const | Var | Add | Mul

def diff(expr: Expr, var: str) -> Expr:
    match expr:
        case Const(_):
            return Const(0)
        case Var(name):
            return Const(1) if name == var else Const(0)
        case Add(f, g):
            return Add(diff(f, var), diff(g, var))
        case Mul(f, g):
            return Add(Mul(f, diff(g, var)), Mul(g, diff(f, var)))

def simplify(expr: Expr) -> Expr:
    match expr:
        case Add(a, b):
            a = simplify(a)
            b = simplify(b)
            match (a, b):
                case (Const(0), _):
                    return b
                case (_, Const(0)):
                    return a
                case _:
                    return Add(a, b)
        case Mul(a, b):
            a = simplify(a)
            b = simplify(b)
            match (a, b):
                case (Const(0), _) | (_, Const(0)):
                    return Const(0)
                case (Const(1), _):
                    return b
                case (_, Const(1)):
                    return a
                case _:
                    return Mul(a, b)
        case _:
            return expr

def showExpr(expr: Expr) -> str:
    match expr:
        case Const(n):
            return str(n)
        case Var(name):
            return name
        case Add(a, b):
            return f"({showExpr(a)} + {showExpr(b)})"
        case Mul(a, b):
            return f"({showExpr(a)} * {showExpr(b)})"

def main():
    expr = Add(Add(Mul(Var("x"), Var("x")), Mul(Const(3), Var("x"))), Const(5))
    derivative = diff(expr, "x")
    simplified = simplify(derivative)
    print(showExpr(simplified))

