  let tree =
    Node(
      Node(Leaf(1), 3, Leaf(0)),
      5,
      Node(Leaf(7), 8, Leaf(9))
    );

  let originalListAll = treeToList(tree);
  let original = filterNonZero(originalListAll);
  println("Original: " ++ showList(original));

